// Both webhooks land here, so everything below deals with one shape.
// A GET carries the rating in the query string; the comment form posts a body.
// Neither is trusted: the token is looked up server-side and the rating is
// re-checked in SQL, so a hand-edited URL gets a polite refusal, not a write.
const supabaseUrl = 'https://hsyuaptfaeydnumnjlzs.supabase.co';

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const q = j.query || {};
  const b = j.body || {};

  const token = String(q.token ?? b.token ?? '').trim();
  const ratingRaw = q.rating ?? b.rating;
  const rating = Number.parseInt(ratingRaw, 10);
  const comment = typeof b.comment === 'string' ? b.comment.slice(0, 1000) : null;

  out.push({
    json: {
      supabaseUrl,
      token,
      rating: Number.isFinite(rating) ? rating : null,
      comment,
      // A comment post with no star is a follow-up to a rating already
      // recorded; the SQL keeps the existing rating in that case.
      isComment: Boolean(comment) && !Number.isFinite(rating),
    },
  });
}
return out;

// Turn the RPC's (ok, message) into the page the person actually sees.
// The comment box is only offered on a successful star click — there is no
// point showing it to someone whose link has expired.
const req = $('Read request').first().json;
const raw = $input.first().json;

// PostgREST returns a one-row table as an array; be tolerant of either shape.
const row = Array.isArray(raw) ? raw[0] : Array.isArray(raw?.data) ? raw.data[0] : raw;
const ok = row?.ok === true;
const message = row?.message || (ok ? 'Thanks — your rating has been saved.' : 'Something went wrong saving that.');

const esc = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const commentForm =
  ok && !req.isComment && !req.comment
    ? `<form method="post" action="./rate-comment" style="margin-top:24px;text-align:left;">
         <input type="hidden" name="token" value="${esc(req.token)}" />
         <label for="c" style="display:block;font-size:14px;margin-bottom:8px;color:#4b5563;">Anything you'd like to add? (optional)</label>
         <textarea id="c" name="comment" rows="4" maxlength="1000" style="width:100%;box-sizing:border-box;padding:10px 12px;border:1px solid #d7dae0;border-radius:8px;font:inherit;font-size:14px;"></textarea>
         <button type="submit" style="margin-top:12px;padding:10px 18px;border:0;border-radius:8px;background:#3b5bdb;color:#fff;font-size:14px;font-weight:600;cursor:pointer;">Send</button>
       </form>`
    : '';

const heading = ok ? 'Thank you' : 'That link did not work';
const stars = ok && req.rating ? `<p style="margin:0 0 4px;font-size:32px;letter-spacing:2px;">${'\u2605'.repeat(req.rating)}<span style="color:#d7dae0;">${'\u2605'.repeat(5 - req.rating)}</span></p>` : '';

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8" /><meta name="viewport" content="width=device-width,initial-scale=1" /><title>${esc(heading)}</title></head>
<body style="margin:0;padding:32px 16px;background:#f4f6f9;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1a1d23;">
  <div style="max-width:480px;margin:0 auto;background:#fff;border:1px solid #e4e7ec;border-radius:12px;padding:32px;text-align:center;">
    ${stars}
    <h1 style="margin:0 0 8px;font-size:22px;">${esc(heading)}</h1>
    <p style="margin:0;font-size:15px;line-height:1.5;color:#4b5563;">${esc(message)}</p>
    ${commentForm}
  </div>
</body></html>`;

return [{ json: { html, statusCode: ok ? 200 : 400 } }];

// The page a star link opens. Deliberately writes NOTHING: link scanners
// fetch every URL in an email, and a GET that recorded a rating would let one
// "click" a star for the user. The person confirms with a real button, which
// POSTs to /rate-submit — the only path that writes. The token is checked
// there (and in SQL), not here, so this page can't be used to probe tokens.
const q = $input.first().json.query || {};
const token = String(q.token ?? '').trim();
const picked = Number.parseInt(q.rating, 10);
const rating = picked >= 1 && picked <= 5 ? picked : 5;

const esc = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const starInputs = [1, 2, 3, 4, 5]
  .map(
    (n) => `<label style="cursor:pointer;display:inline-flex;flex-direction:column;align-items:center;gap:4px;">
      <input type="radio" name="rating" value="${n}" ${n === rating ? 'checked' : ''} style="accent-color:#3b5bdb;" />
      <span style="font-size:22px;color:#f5a524;" aria-label="${n} star${n === 1 ? '' : 's'}">${'★'.repeat(n)}</span>
    </label>`
  )
  .join('');

const body = token
  ? `<h1 style="margin:0 0 8px;font-size:22px;">Rate Jobassist</h1>
    <p style="margin:0 0 20px;font-size:15px;line-height:1.5;color:#4b5563;">Check your rating, add a note if you like, and press Submit.</p>
    <form method="post" action="./rate-submit" style="text-align:left;">
      <input type="hidden" name="token" value="${esc(token)}" />
      <fieldset style="border:0;margin:0 0 20px;padding:0;display:flex;justify-content:space-between;gap:4px;flex-wrap:wrap;">
        <legend style="font-size:14px;margin-bottom:8px;color:#4b5563;">Your rating</legend>
        ${starInputs}
      </fieldset>
      <label for="c" style="display:block;font-size:14px;margin-bottom:8px;color:#4b5563;">Anything you'd like to add? (optional)</label>
      <textarea id="c" name="comment" rows="4" maxlength="1000" style="width:100%;box-sizing:border-box;padding:10px 12px;border:1px solid #d7dae0;border-radius:8px;font:inherit;font-size:14px;"></textarea>
      <button type="submit" style="margin-top:12px;padding:10px 18px;border:0;border-radius:8px;background:#3b5bdb;color:#fff;font-size:14px;font-weight:600;cursor:pointer;">Submit rating</button>
    </form>`
  : `<h1 style="margin:0 0 8px;font-size:22px;">That link did not work</h1>
    <p style="margin:0;font-size:15px;line-height:1.5;color:#4b5563;">This rating link is incomplete. Try the link in the email again.</p>`;

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8" /><meta name="viewport" content="width=device-width,initial-scale=1" /><meta name="robots" content="noindex" /><title>Rate Jobassist</title></head>
<body style="margin:0;padding:32px 16px;background:#f4f6f9;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1a1d23;">
  <div style="max-width:480px;margin:0 auto;background:#fff;border:1px solid #e4e7ec;border-radius:12px;padding:32px;text-align:center;">
    ${body}
  </div>
</body></html>`;

return [{ json: { html, statusCode: token ? 200 : 400 } }];
